// Enhanced Shader with Dynamic Colors

// Function to create a dynamic color palette
vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.4, 0.7); // Base color
    vec3 b = vec3(0.5, 0.5, 0.5); // Variation in brightness
    vec3 c = vec3(1.0, 0.7, 0.5); // Hue offsets
    vec3 d = vec3(0.3, 0.2, 0.1); // Time-based color shift

    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize fragment coordinates
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // Add interaction with the mouse to modify visuals
    uv += vec2(iMouse.xy / iResolution.xy - 0.5) * 2.0;

    vec3 finalColor = vec3(0.0);

    for (float i = 0.0; i < 6.0; i++) { // Increase iterations for more detail
        uv = fract(uv * 1.8) - 0.5;

        float d = length(uv) * exp(-length(uv0));

        vec3 col = palette(length(uv0) + i * 0.5 + iTime * 0.6);

        d = sin(d * 10.0 + iTime) / 10.0;
        d = abs(d);

        d = pow(0.02 / d, 1.3); // Adjusted exponent for smoother visuals

        finalColor += col * d;
    }

    // Add a swirling rainbow effect
    float rainbow = 0.5 + 0.5 * sin(iTime + uv.x * 4.0 + uv.y * 4.0);
    finalColor *= vec3(rainbow, 1.0 - rainbow, 0.8 + 0.2 * rainbow);

    // Blend a radial gradient for a glowing effect
    float glow = exp(-10.0 * length(uv0));
    finalColor += vec3(0.2, 0.4, 0.6) * glow;

    // Output the final color
    fragColor = vec4(finalColor, 1.0);
}
